public final class Config {
  private static volatile Config instance;
  private Config() { /* đọc file cấu hình */ }

  public static Config getInstance() {
    if (instance == null) {                 // kiểm tra lần 1, không khoá
      synchronized (Config.class) {
        if (instance == null) instance = new Config(); // kiểm tra lần 2
      }
    }
    return instance;
  }
}

